-- Queer Atlas: verified Canadian queer events and queer-techno parties.
-- Researched 2026-09-26 from organisers, ticketing partners and Resident Advisor.
-- Confidential warehouse addresses are deliberately never inferred.

begin;

alter table if exists public.events
  add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events
  add column if not exists ticket_url text;

with src as (
  select * from jsonb_to_recordset($qa_canada_events$
[
{"name":"Pikete x Club Bebe (Van): CUERPOS","aliases":["CUERPOS Montreal 2026","Pikete Club Bebe Cuerpos"],"city":"montreal","date":"2026-10-03","start_date":"2026-10-03","end_date":"2026-10-04","description":"Pikete and Vancouver's Club Bébé splice Montréal and Vancouver into one sweaty queer Latinx transmission: baile funk, Latin bass, Lusophone club mutations and dancers who treat the floor as a place to move without fear or limits.","link":"https://ra.co/events/2543412","ticket_url":"https://ra.co/events/2543412","location":"ESC, 2023 Boulevard Saint-Laurent, Montréal, QC H2X 2T3, Canada","lat":45.51948,"lng":-73.56855,"vibe":"queer Latinx baile funk and Latin bass marathon with radical dance-floor release","intel":{"hours":"22:00–06:00 Saturday 3 October into Sunday 4 October 2026.","entry_wait":"Tickets were listed at CA$15–30 through the organiser's Zeffy link; buy ahead rather than betting on a late door.","best_arrival":"Arrive close to 22:00 for the full eight-hour arc and easier entry before the floor reaches late-night density.","crowd_mix":"Queer Latinx dancers, Montréal and Vancouver collectives, Lusophone club heads and local allies are directly centred.","dress_code":"No formal threshold is published; expressive dance-ready clothing is welcome without a fetish requirement.","host_inclusivity":"The organisers explicitly frame CUERPOS as a queer Latinx experience where bodies can dance without fear or limits.","lineup":"CUERPOS, BINKY, Brendocha, BADJUDA, mCherry, La Niña Kiwi, DJ Punani, Karukasy.","age_limit":"18+.","source_urls":["https://ra.co/events/2543412"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"ROTE8: The Advent (UK) & Lewis Fautzi (PRT)","aliases":["ROTE8 The Advent Lewis Fautzi 2026"],"city":"toronto","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"ROTE8 pairs The Advent's industrial scar tissue with Lewis Fautzi's hardware pressure, then asks Toronto to meet it with consent, neurodivergent awareness and actual attention to the dance floor. This is hard techno with a published care framework, not a rainbow sticker on a warehouse door.","link":"https://ra.co/events/2539903","ticket_url":"https://ra.co/events/2539903","location":"Toronto, ON, Canada — warehouse address shared only with ticket holders","lat":43.65323,"lng":-79.38318,"vibe":"LGBTQIA+-friendly industrial techno warehouse with consent-first floor discipline","intel":{"hours":"22:00–05:00 Saturday 10 October into Sunday 11 October 2026.","entry_wait":"Ticket holders receive the warehouse address. Bring 19+ ID and do not travel to a guessed venue; admission remains subject to the organiser's terms.","best_arrival":"Be ready at 22:00 and follow the ticket-holder location message, rather than arriving late to a confidential warehouse.","crowd_mix":"The event is explicitly LGBTQIA+ and neurodivergent-friendly while welcoming serious techno dancers who respect the shared floor.","dress_code":"No published costume rule. Ear protection, practical dark layers and a phone-away dance-floor mindset fit the stated format.","host_inclusivity":"ROTE8 publishes consent guidance, bans dance-floor chatter and flash photography, and explicitly identifies the night as LGBTQIA+ and neurodivergent-friendly.","lineup":"The Advent, Lewis Fautzi, Lee Osborne, Marivs.","age_limit":"19+.","source_urls":["https://ra.co/events/2539903"],"research_status":"ticketing_listing_verified_confidential_address","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"forever night 4","aliases":["Forever Night 4 Toronto","forever night four"],"city":"toronto","date":"2026-10-16","start_date":"2026-10-16","end_date":"2026-10-17","description":"Forever Night turns its first birthday into a two-floor pre-Halloween argument for Toronto's left-field club scene: Mutualism, stiff dance, Zola and a deep local bill ricochet between techno, house, electro and bass. Queer artists are materially present in the lineup, though the organiser does not present it as a queer-exclusive event.","link":"https://ra.co/events/2531036","ticket_url":"https://ra.co/events/2531036","location":"The Jama, 961 College Street, Toronto, ON M6H 1A6, Canada","lat":43.65393,"lng":-79.43297,"vibe":"two-floor queer-connected techno, electro, bass and club chaos before Halloween","intel":{"hours":"22:00–04:00 Friday 16 October into Saturday 17 October 2026.","entry_wait":"Use the current RA ticket listing; two active floors and an anniversary bill make late walk-up capacity uncertain.","best_arrival":"Arrive just after doors to catch both room trajectories before the Halloween-season crowd compresses the venue.","crowd_mix":"Toronto electronic-music regulars, queer artists and friends of the promoter form a mixed, music-first audience; it is not sold as queer-exclusive.","dress_code":"No stated rule. Halloween-adjacent self-expression works, but no fetish or costume threshold is published.","host_inclusivity":"Queer representation is present through artists and scene links, but no independent safer-space policy was published; the event should not be overstated as a dedicated queer venue night.","lineup":"Mutualism, BIP b2b GRRLCRRSH, Zola, Critter, Aji, stiff dance, dj miss, loverose.","age_limit":"Not published on the current listing; check ticket terms before travel.","source_urls":["https://ra.co/events/2531036"],"research_status":"ticketing_listing_verified_queer_connected_not_exclusive","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"SWEA(T): LaFHomme, JASHIM, EvidenceDoll, Zellers","aliases":["SWEAT TransmascMTL October 2026","SWEA(T) Montreal 2026"],"city":"montreal","date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-18","description":"SWEA(T) hands ESC to eight hours of transmasculine selectors, gogo/pole performers, heavy bass and sensual dark-room pressure. It is proudly queer and trans, centred on transmasculine people without turning everyone else into an afterthought.","link":"https://ra.co/events/2540053","ticket_url":"https://ra.co/events/2540053","location":"ESC, 2023 Boulevard Saint-Laurent, Montréal, QC H2X 2T3, Canada","lat":45.51948,"lng":-73.56855,"vibe":"transmasculine-centred queer techno and club night with bass, dancers and dark-room energy","intel":{"hours":"22:00–06:00 Saturday 17 October into Sunday 18 October 2026.","entry_wait":"Buy through the current ticket link and arrive before midnight if you want a simpler entry to an eight-hour, capacity-bound room.","best_arrival":"Start near 22:00 to experience the performers and DJ arc before the sunrise push.","crowd_mix":"Transmasculine people are explicitly centred; trans and cis tboy appreciators are invited into a queer and trans space.","dress_code":"No strict code is published. Sensual, dance-ready and expressive clothing suits the atmosphere without becoming a required look.","host_inclusivity":"TransmascMTL explicitly describes SWEA(T) as a queer and trans space centred on transmasculine people.","lineup":"LaFHomme, JASHIM, Zellers, EvidenceDoll.","age_limit":"18+.","source_urls":["https://ra.co/events/2540053"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"AYC Presents: The Masc-querade Ball","aliases":["AYC Masc-querade Ball 2026","The Mascquerade Ball Toronto"],"city":"toronto","date":"2026-10-31","start_date":"2026-10-31","end_date":"2026-11-01","description":"ATYOURCRUX turns Longboat Hall into a Halloween masc-querade where masks, masc play and Berlin-leaning industrial techno replace ordinary costume-party autopilot. Katamina's Montréal queer collective arrives alongside a deliberately freaky local bill.","link":"https://ra.co/events/2539424","ticket_url":"https://ra.co/events/2539424","location":"Longboat Hall, 103 Dovercourt Road, Toronto, ON M6J 3C6, Canada","lat":43.64387,"lng":-79.42046,"vibe":"queer Halloween industrial techno and EBM ball with masks, masc play and theatrical pressure","intel":{"hours":"22:00–03:00 Saturday 31 October into Sunday 1 November 2026.","entry_wait":"Very limited door tickets are subject to capacity; purchase in advance and bring mandatory 19+ identification.","best_arrival":"Arrive for 22:00 doors to take in the full sequence and avoid the post-midnight Halloween bottleneck.","crowd_mix":"Queer clubbers, masc-of-centre guests, Montreal's virtualisvirtualis orbit and Halloween-techno dancers form the expected room.","dress_code":"Masks or a hot masc look are invited, not made into a rigid identity test; retain footwear suitable for a full club night.","host_inclusivity":"The bill consciously brings a Montréal queer collective into Toronto's queer Halloween space; use the host's event rules for current support contacts.","lineup":"Kaylub, DR4SKYN, Katamina, MIX SIGNALS, EMRYSLAZULI.","age_limit":"19+.","source_urls":["https://ra.co/events/2539424"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Pink Awards 2026","aliases":["Pink Triangle Press Pink Awards 2026"],"city":"toronto","date":"2026-11-05","start_date":"2026-11-05","end_date":"2026-11-05","description":"Pink Triangle Press gathers Toronto's 2SLGBTQIA+ media, community and cultural ecosystem for the Pink Awards, with Peppermint and Brandon Ash-Mohammed hosting an evening that treats queer achievement as a room worth dressing for, not a sidebar.","link":"https://www.pinktrianglepress.com/pink-triangle-press-announces-the-2026-pink-awards-with-host-peppermint-and-co-host-brandon-ash-mohammed/","ticket_url":"https://www.pinktrianglepress.com/pink-triangle-press-announces-the-2026-pink-awards-with-host-peppermint-and-co-host-brandon-ash-mohammed/","location":"Fairmont Royal York, 100 Front Street West, Toronto, ON M5J 1E3, Canada","lat":43.64526,"lng":-79.38192,"vibe":"polished 2SLGBTQIA+ awards night blending queer media, performance and community recognition","intel":{"hours":"5 November 2026; final public door and programme times should be confirmed with the organiser.","entry_wait":"Use the organiser's current award-page and ticket guidance; a hotel gala should be approached as a booked event, not a casual bar walk-in.","best_arrival":"Arrive before the announced programme start for red-carpet, registration and seating logistics once the final timing is released.","crowd_mix":"2SLGBTQIA+ media makers, honourees, advocates, entertainers, industry guests and supporters are the event's intended community.","dress_code":"Gala or polished cocktail attire is the sensible read; confirm any final theme or accessibility guidance with the organiser.","host_inclusivity":"Pink Triangle Press is a long-running 2SLGBTQIA+ media organisation, and the awards explicitly celebrate the community's diversity and achievement.","lineup":"Hosted by Peppermint and Brandon Ash-Mohammed; further programme details to be confirmed.","age_limit":"Not published; confirm with organiser.","source_urls":["https://www.pinktrianglepress.com/pink-triangle-press-announces-the-2026-pink-awards-with-host-peppermint-and-co-host-brandon-ash-mohammed/"],"research_status":"official_announcement_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"CQCC Black & White Gala: In Full Colour","aliases":["CQCC 11th Annual Black and White Gala 2026","Black & White Gala In Full Colour"],"city":"toronto","date":"2026-11-13","start_date":"2026-11-13","end_date":"2026-11-13","description":"The Canadian Queer Chamber of Commerce's Black & White Gala goes In Full Colour at The Carlu: an evening for 2SLGBTQI+ business leaders, stories and real community connection, where the polished setting serves a substantive queer network rather than empty corporate rainbow theatre.","link":"https://www.eventbrite.ca/e/cqccs-11th-annual-black-white-gala-in-full-colour-tickets-1999058421552","ticket_url":"https://www.eventbrite.ca/e/cqccs-11th-annual-black-white-gala-in-full-colour-tickets-1999058421552","location":"The Carlu, 444 Yonge Street, Toronto, ON M5B 2H4, Canada","lat":43.66050,"lng":-79.38329,"vibe":"formal 2SLGBTQI+ business-community gala with recognition, conversation and celebration","intel":{"hours":"18:00–23:30 Friday 13 November 2026.","entry_wait":"Ticketed Eventbrite gala with refunds available up to seven days before the event; reserve rather than expecting door admission.","best_arrival":"Arrive near 18:00 for check-in, networking and the event's opening social window.","crowd_mix":"Queer entrepreneurs, business owners, professionals, award supporters, community leaders and allies gather around 2SLGBTQI+ achievement.","dress_code":"Black-tie or polished gala dressing is appropriate; confirm any specific 'In Full Colour' styling guidance before the event.","host_inclusivity":"The Canadian Queer Chamber of Commerce presents the evening specifically to celebrate 2SLGBTQI+ excellence and make community connections.","lineup":"Recognition, entertainment and community programming; final performers to be confirmed by CQCC.","age_limit":"Not published; confirm with organiser.","source_urls":["https://www.eventbrite.ca/e/cqccs-11th-annual-black-white-gala-in-full-colour-tickets-1999058421552"],"research_status":"official_ticketing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Cirque de Boudoir Vancouver","aliases":["Cirque de Boudoir Vancouver 2026","CDB Vancouver 2026"],"city":"vancouver","date":"2026-11-14","start_date":"2026-11-14","end_date":"2026-11-15","description":"Cirque de Boudoir brings twenty years of Montréal fetish-circus imagination to Vancouver's Skylight Warehouse: kink, costume, dance and theatrical excess in a private queer-run room where the dress code is part of the art rather than a vague aesthetic suggestion.","link":"https://www.cirquedeboudoir.com/en/events/2026-11_cirque-de-boudoir-vancouver","ticket_url":"https://www.cirquedeboudoir.com/en/events/2026-11_cirque-de-boudoir-vancouver","location":"Skylight Warehouse, 1800 Main Street, Vancouver, BC, Canada","lat":49.27096,"lng":-123.10170,"vibe":"queer-run fetish circus warehouse party built on costume, kink and theatrical nightlife","intel":{"hours":"From 21:30 Saturday 14 November 2026; confirm final closing time with the organiser.","entry_wait":"Advance tickets and a strict creative dress code apply. The organiser states that no-effort casual looks are refused, so do not assume a ticket alone guarantees entry.","best_arrival":"Reach the warehouse near 21:30 with your look complete; this gives time for door review and the full circus-world build.","crowd_mix":"LGBTQ+, straight, bi-curious, masc, femme, non-binary, drag, couples, solo guests, ravers and curious newcomers are all explicitly welcomed.","dress_code":"Strict fetish-circus creativity: no jeans, plain T-shirts, sneakers or casual clothing. DIY, vintage, mesh, harnesses, body paint and inventive alternatives are welcomed.","host_inclusivity":"The organiser explicitly welcomes identities, bodies and experience levels, while pairing that openness with a published code of conduct and consent rules.","lineup":"DJ DAVIDÉ and VJ BUNNYGUTS lead the 20th-anniversary touring production; final local programme via organiser.","age_limit":"Confirm ticket terms before travel.","source_urls":["https://www.cirquedeboudoir.com/en/events/2026-11_cirque-de-boudoir-vancouver","https://www.cirquedeboudoir.com/en/dresscode","https://www.cirquedeboudoir.com/en/rules"],"research_status":"official_event_and_house_rules_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Présente ton ami! (gay/queer edition)","aliases":["Presente ton ami gay queer November 2026","Présente ton ami! Édition hommes gais queer"],"city":"montreal","date":"2026-11-18","start_date":"2026-11-18","end_date":"2026-11-18","description":"Match-moi lets queer friends pitch their single friends onstage with slides, jokes and actual affection: a gay and non-binary edition of dating where wingpeople, not algorithms, build the room's first spark.","link":"https://thepointofsale.com/tickets/ptagaiqueer","ticket_url":"https://thepointofsale.com/tickets/ptagaiqueer","location":"Stock Cabaret, 1171 Rue Sainte-Catherine Est, Montréal, QC H2L 2G8, Canada","lat":45.52413,"lng":-73.55372,"vibe":"warm queer dating show where friends, slides and conversation replace swipe fatigue","intel":{"hours":"19:30–22:00 Wednesday 18 November 2026; doors open at 19:00 and presentations begin at 20:00.","entry_wait":"Arrive at least thirty minutes early as the organiser recommends, allowing time for check-in, wristbands and conversation before the presentations.","best_arrival":"Target 19:30: it creates social space before the 20:00 show without arriving so early that the room is still empty.","crowd_mix":"Gay men and non-binary queer singles are the edition's focus, while coupled guests and queer allies can join as supportive wingpeople.","dress_code":"No formal code is published; approachable date-night clothing fits better than nightclub performance dressing.","host_inclusivity":"Match-moi states that single, partnered and ally guests are welcome, with wristbands that let people communicate relationship status without guessing.","lineup":"Around ten single queer people are introduced by friends through short presentations.","age_limit":"Confirm with ticket provider before purchase.","source_urls":["https://thepointofsale.com/tickets/ptagaiqueer"],"research_status":"official_ticketing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"PURR: A Kinky Kitty Sexy Rave","aliases":["PURR Vancouver November 2026","PURR Kinky Kitty Sexy Rave 2026"],"city":"vancouver","date":"2026-11-21","start_date":"2026-11-21","end_date":"2026-11-22","description":"PURR takes Vancouver's Skylight Warehouse from cute to carnivorous: a private multi-room rave of dirty basslines, DJs, performers, vendors and consent-led kink play where queer nightlife, electronic music and creative self-invention keep each other moving.","link":"https://www.showpass.com/fr/purr-nov21-tickets/","ticket_url":"https://www.showpass.com/fr/purr-nov21-tickets/","location":"Skylight Warehouse, 1800 Main Street, Vancouver, BC, Canada","lat":49.27096,"lng":-123.10170,"vibe":"consent-led queer kinky warehouse rave with multi-room electronic energy and play spaces","intel":{"hours":"21:30–02:30 Saturday 21 November into Sunday 22 November 2026.","entry_wait":"Tickets were CA$33.77–44.34 and the organiser warns that PURR regularly fills. Buy ahead; newsletter subscribers receive first access to future editions.","best_arrival":"Arrive at 21:30 for the smoother door and time to understand the venue's multi-room layout before the packed peak.","crowd_mix":"LGBTQ+ communities, electronic-music fans, kink communities, lifestylers, solo guests, couples and curious newcomers are invited into the consent-based format.","dress_code":"The current ticket page does not impose a strict clothing rule; choose creative, dance-safe attire and follow any event-day consent or play-space guidance.","host_inclusivity":"Restricted Entertainment presents PURR as a safe, consent-based environment for LGBTQ+ communities and varied relationship and identity expressions.","lineup":"DJs, performers, vendors and multiple play areas; final artist bill via organiser.","age_limit":"Confirm ticket terms before travel.","source_urls":["https://www.showpass.com/fr/purr-nov21-tickets/"],"research_status":"official_ticketing_verified","updated_at":"2026-09-26T00:00:00Z"}}
]
$qa_canada_events$) e(name text,aliases jsonb,city text,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), matched as (
  select s.*, existing.id as existing_id from src s left join lateral (
    select e.id from public.events e where lower(trim(e.city))=lower(trim(s.city)) and (
      lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi'))
      or exists (select 1 from jsonb_array_elements_text(coalesce(s.aliases,'[]'::jsonb)) a where lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi')))
      or (e.start_date=s.start_date and lower(nullif(trim(e.link),'')) in (lower(trim(s.link)),lower(trim(s.ticket_url))))
    ) order by e.updated_at desc nulls last limit 1
  ) existing on true
), updated as (
  update public.events e set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from matched s where e.id=s.existing_id returning e.id
)
insert into public.events(name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from matched where existing_id is null;

do $qa_canada_event_guard$
begin
  if exists (select 1 from public.events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'Imported Canadian event missing description, location or source'; end if;
  if exists (select 1 from public.events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' group by lower(trim(city)),lower(regexp_replace(trim(name),'[^a-z0-9]+','','gi')),start_date having count(*)>1) then raise exception 'Duplicate Canadian event detected'; end if;
end;
$qa_canada_event_guard$;

commit;
